UPDATE ${tableName}
SET customer =  #{model.customer},
    buyer_name =  #{model.buyerName},
 quotation_number = #{model.quotationNumber},
 payment_strategy = #{model.paymentStrategy},
 quotation_amount =  #{model.quotationAmount},
 deal_time =  #{model.dealTime},
 deal_amount = #{model.dealAmount}
WHERE primary_key =#{model.filingCode}
  AND enterprise_code = #{model.enterpriseCode}

UPDATE ${tableName}
SET
    deal_amount = #{dealAmount}
WHERE sell_quotation =#{sellQuotationCode}
  AND enterprise_code = #{enterpriseCode}

UPDATE ${tableName}
SET
    read_flag = true
WHERE primary_key =#{filingCode}
  AND enterprise_code = #{enterpriseCode}

mapper.select:
SELECT primary_key as filingCode, enterprise_code, buyer_name, seller, customer, sell_quotation, quotation_number, filing_time, remark, payment_strategy, quotation_amount, deal_time, deal_amount, business_belong, read_flag FROM ${tableName} WHERE enterprise_code= #{enterpriseCode} AND delete_flag= 'f'
AND buyer_name LIKE '%'|| #{buyerName} ||'%'
AND seller IN
#{seller}
AND payment_strategy LIKE '%'|| #{paymentStrategy} ||'%'
AND filing_time >= #{filingTimePreDate}
AND filing_time <= #{filingTimePostDate}
AND business_belong = #{businessBelong}
ORDER BY id DESC
